"""Разделы 2.3, 2.4, 2.5 отчета ЛР1."""
from rep_common import A, H, P, figure, num, pct, table


def ywq(q):
    return next(x for x in A["yw_queries"] if x["query"] == q)


def gtq(pack, q):
    return next(x for x in A["gt_queries"] if x["pack"] == pack and x["query"] == q)


def run():
    # ---------------- Google Trends
    H(3, "2.3 Google Trends")
    P("Google Trends используется для оценки относительной динамики интереса и сравнения запросов; индекс нормирован внутри выбранного набора условий и не равен числу запросов [1], [2].")
    H(4, "2.3.1 Настройки и протокол")
    P("Данные Google Trends выгружены 02.10.2026 со страницы сервиса под учетной записью владельца проекта. Настройки зафиксированы единые для всех пакетов (таблица [[t:gt_set]]); в каждом пакете сравнивалось не более пяти запросов [2]. Значения получены из ответов интерфейса сервиса (те же данные, что отображаются на графиках); файлы CSV через кнопку скачивания не сохранялись, источник данных и контрольные суммы рядов приведены в журнале выгрузки (таблица [[t:journal]]).")
