    def lev_a(v):
        return "высокий (60-100)" if v >= 60 else ("средний (30-59)" if v >= 30 else ("низкий (10-29)" if v >= 10 else "недостаточный (0-9)"))

    def lev_b(v):
        return "высокая выраженность (70-100)" if v >= 70 else ("средний (40-69)" if v >= 40 else ("нишевый (20-39)" if v >= 20 else "низкий или недостаточно данных (0-19)"))
